        layer_result = {"heads": {}}

        for head_idx in range(num_q_heads):
            kv_idx = head_idx // heads_per_group
            q_head = q[:, head_idx:head_idx+1, :, :]
            k_head = k[:, kv_idx:kv_idx+1, :, :]

            head_bands = {}
            for band_name, band_range in BANDS.items():
