                k_tbab = apply_rope_band(k_head, std_pos, band_range, INV_FREQ)
                # Recompute with TBAB positions (different RoPE angles)
                q_tbab = apply_rope_band(q_head, tbab_pos[:, :seq_len], band_range, INV_FREQ)
                k_tbab = apply_rope_band(k_head, tbab_pos[:, :seq_len], band_range, INV_FREQ)
                attn_tbab = compute_cross_turn_attention(
                    q_tbab, k_tbab, std_boundaries, seq_len,
                )

