def aggregate_results(all_results: List[Dict]) -> Dict:
    """Aggregate per-sample results into summary statistics.

    Key metric: fraction of heads where mid-freq improvement > max(high, low).
    """
    head_votes = {}

    for sample_result in all_results:
        if sample_result.get("skip"):
            continue
        for l_idx, layer_data in sample_result["layers"].items():
            for h_idx, band_data in layer_data["heads"].items():
                key = (l_idx, h_idx)
                if key not in head_votes:
                    head_votes[key] = {"mid_wins": 0, "total": 0}

                mid_imp = band_data["mid_freq"]["improvement"]
                low_imp = band_data["low_freq"]["improvement"]
                high_imp = band_data["high_freq"]["improvement"]

                head_votes[key]["total"] += 1
                if mid_imp > low_imp and mid_imp > high_imp:
                    head_votes[key]["mid_wins"] += 1

    total_heads = len(head_votes)
    if total_heads == 0:
        return {"pass": False, "ratio": 0.0, "total_heads": 0}

    mid_dominant_heads = sum(
        1 for v in head_votes.values()
        if v["total"] > 0 and v["mid_wins"] / v["total"] > 0.5
    )
    ratio = mid_dominant_heads / total_heads

    per_band_mean = {"low_freq": [], "mid_freq": [], "high_freq": []}
    for sample_result in all_results:
        if sample_result.get("skip"):
            continue
        for l_idx, layer_data in sample_result["layers"].items():
            for h_idx, band_data in layer_data["heads"].items():
                for band in per_band_mean:
                    per_band_mean[band].append(band_data[band]["improvement"])

    return {
        "pass": ratio >= 0.6,
        "mid_dominant_ratio": round(ratio, 4),
        "total_heads_analyzed": total_heads,
        "mean_improvement": {
            band: round(float(np.mean(vals)), 6) if vals else 0.0
            for band, vals in per_band_mean.items()
        },
    }


def run_attention_analysis(
    model,
    tokenizer,
    conversations: List[List[Dict[str, str]]],
    bridge_token_ids: Optional[List[int]] = None,
    layers: Optional[List[int]] = None,
    output_path: Optional[str] = None,
) -> Dict:
    """Run full per-band attention analysis on a set of conversations.

    Args:
        model: loaded MistralForCausalLM (with or without LoRA merged)
        tokenizer: corresponding tokenizer
        conversations: list of message lists
        bridge_token_ids: bridge token IDs for TBAB condition
        layers: which layers to analyze (None = all)
        output_path: optional path to save detailed results

    Returns:
        summary dict with pass/fail and per-band statistics
    """
    all_results = []
    for i, messages in enumerate(conversations):
        print(f"  Analyzing sample {i+1}/{len(conversations)}...", flush=True)
        result = analyze_single_sample(
            model, tokenizer, messages, bridge_token_ids, layers,
        )
        all_results.append(result)

    summary = aggregate_results(all_results)

    if output_path:
        serializable = []
        for r in all_results:
            if r.get("skip"):
                serializable.append(r)
                continue
            sr = {"num_turns": r["num_turns"], "layers": {}}
            for l, ld in r["layers"].items():
                sr["layers"][str(l)] = {
                    "heads": {str(h): hd for h, hd in ld["heads"].items()}
                }
            serializable.append(sr)

        with open(output_path, "w") as f:
            json.dump({"summary": summary, "samples": serializable}, f, indent=2)
        print(f"  Detailed results saved to {output_path}")

    return summary
